"""Controlled expansion batch 007: purple sweet potato and Trachystemon tables."""
from pathlib import Path
import hashlib,json
import pandas as pd
R=Path(__file__).resolve().parent; PARENT=R.parent/'batch_006'/'updated_master_dataset.csv'
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,t): (R/n).write_text(t.strip()+'\n',encoding='utf-8')
base=pd.read_csv(PARENT)
def template(name):
 f=base.loc[base.compound.astype(str).str.casefold().eq(name.casefold())];assert len(f),name;return f.iloc[0]
def add(src, **kw):
 row={c:src[c] for c in base.columns};row.update(kw);row.update({'original_record_id':'','target_name':'apparent_concentration_ratio_percent','target_equation':'100 * C_cooked / C_raw','target_value_percent':100*kw['cooked_concentration']/kw['raw_concentration'],'target_semantics':'apparent concentration ratio; not total-mass retention','evidence_status':'VERIFIED_PRIMARY_TABLE','cooked_yield_status':'NOT_REPORTED','total_mass_retention_status':'NOT_ESTABLISHED'});rows.append(row)
rows=[]
# Chen et al. 2017, Table 4: HPLC individual phenolic acids; DW table values.
psp={'Chlorogenic Acid':(176.67,[('Steaming','steaming',206.62,100,30,'steam'),('Microwave then steaming','microwave then steaming',270.27,100,17,'800 W 2 min then steam 100 C 15 min'),('Steaming then microwave','steaming then microwave',305.89,100,13,'steam 100 C 10 min then 800 W 3 min'),('Microwaving','microwave',239.41,pd.NA,5,'800 W')]),'Caffeic acid':(2.19,[('Steaming','steaming',2.16,100,30,'steam'),('Microwave then steaming','microwave then steaming',2.02,100,17,'800 W 2 min then steam 100 C 15 min'),('Steaming then microwave','steaming then microwave',2.05,100,13,'steam 100 C 10 min then 800 W 3 min'),('Microwaving','microwave',1.89,pd.NA,5,'800 W')]),'p-Coumaric acid':(5.04,[('Steaming','steaming',9.40,100,30,'steam'),('Microwave then steaming','microwave then steaming',8.40,100,17,'800 W 2 min then steam 100 C 15 min'),('Steaming then microwave','steaming then microwave',9.82,100,13,'steam 100 C 10 min then 800 W 3 min'),('Microwaving','microwave',9.82,pd.NA,5,'800 W')])}
for compound,(raw,treatments) in psp.items():
 for method,norm,cooked,temp,mins,medium in treatments:
  safe=compound.upper().replace(' ','_').replace('-','_');add(template(compound),observation_id=f'LIT-CHEN2017-PURPLE_SWEET_POTATO-{safe}-{norm.upper().replace(" ","_").replace("-","_")}',doi='10.3136/fstr.23.193',paper_id='NEW_LITERATURE_CHEN_2017',source_locator='Table 4; Methods: Cooking techniques and phenolic acids analysis',compound=compound,food_matrix='Purple sweet potato (Ipomoea batatas)',cooking_method=method,cooking_method_normalized=norm,cooking_medium=medium,raw_concentration=raw,cooked_concentration=cooked,concentration_unit='mg/100 g dry weight',measurement_basis='dry weight (DW)',source_detail='Chen et al. (2017), Table 4. Individual HPLC phenolic acid; table reports mg/100 g DW. Each cooking procedure performed in triplicate; Table 4 has no SD values.',Temperature_C=temp,Cooking_Time_min=mins,raw_sd=pd.NA,cooked_sd=pd.NA,reported_replicate_design='Each cooking procedure performed in triplicate; one row per treatment mean',analytical_definition='Individual HPLC UV phenolic acid; freeze-dried cooked material')
# Demirel Ozbek et al. 2024, Table 2: only caffeic acid has a positive raw value.
trach=[('Boiling','boiling',5,19.56,0.88,97.3,'400 mL water / 100 g'),('Boiling','boiling',10,33.47,1.49,97.3,'400 mL water / 100 g'),('Boiling','boiling',15,38.43,1.67,97.3,'400 mL water / 100 g'),('Steaming','steaming',5,7.77,0.56,97.3,'steam; water volume not reported'),('Steaming','steaming',10,1.01,0.04,97.3,'steam; water volume not reported'),('Steaming','steaming',15,1.36,0.04,97.3,'steam; water volume not reported'),('Stir-frying','stir-frying',5,175.87,2.00,180,'10 mL sunflower oil / 100 g'),('Stir-frying','stir-frying',10,214.22,2.21,180,'10 mL sunflower oil / 100 g'),('Stir-frying','stir-frying',15,1107.38,3.47,180,'10 mL sunflower oil / 100 g'),('Microwaving','microwave',3,129.15,2.61,pd.NA,'10 mL distilled water / 100 g; 600 W'),('Microwaving','microwave',5,179.13,1.99,pd.NA,'10 mL distilled water / 100 g; 600 W'),('Microwaving','microwave',7,487.65,3.74,pd.NA,'10 mL distilled water / 100 g; 600 W'),('Sous vide','sous vide',15,201.95,3.57,80,'vacuum packaged'),('Sous vide','sous vide',30,82.53,2.11,80,'vacuum packaged'),('Sous vide','sous vide',45,86.11,2.04,80,'vacuum packaged')]
for method,norm,mins,cooked,sd,temp,medium in trach:
 add(template('Caffeic acid'),observation_id=f'LIT-OZBEK2024-TRACHYSTEMON_LEAF_STEM-CAFFEIC_ACID-{norm.upper().replace(" ","_")}-{str(mins).replace(".","_")}MIN',doi='10.1371/journal.pone.0299037',paper_id='NEW_LITERATURE_OZBEK_2024',source_locator='Table 2; Methods: Cooking methods and determination of phenolic compounds',compound='Caffeic acid',food_matrix='Trachystemon leaf and stem (Trachystemon orientalis)',cooking_method=method,cooking_method_normalized=norm,cooking_medium=medium,raw_concentration=31.53,cooked_concentration=cooked,concentration_unit='mg/100 g dry weight',measurement_basis='dry weight (DW)',source_detail='Demirel Ozbek et al. (2024), Table 2. Individual HPLC-UV caffeic acid, raw and cooked; values mean ± SD, three samples per raw and condition.',Temperature_C=temp,Cooking_Time_min=mins,raw_sd=0.25,cooked_sd=sd,reported_replicate_design='Three 100 g samples per raw and cooking condition; Table 2 mean ± SD',analytical_definition='Individual HPLC-UV phenolic compound; dry-matter calculations')
new=pd.DataFrame(rows,columns=base.columns);master=pd.concat([base,new],ignore_index=True)
assert len(new)==27 and len(master)==600 and master.doi.nunique()==20
assert new.canonical_molecular_id.notna().all() and not master.observation_id.duplicated().any();assert (new.target_value_percent.round(8)==(100*new.cooked_concentration/new.raw_concentration).round(8)).all()
master.to_csv(R/'updated_master_dataset.csv',index=False);new.to_csv(R/'verified_observations.csv',index=False);new.to_csv(R/'extracted_observations.csv',index=False)
pd.DataFrame([{'doi':'10.3136/fstr.23.193','title':'Combined Effect of Microwave and Steam Cooking on Phytochemical Compounds and Antioxidant Activity of Purple Sweet Potatoes','year':2017,'admitted_rows':12,'status':'VERIFIED_PARTIAL','basis':'mg/100 g dry weight','reason':'Table 4 individual HPLC acids; only exact current identities admitted. Vanillic and p-hydroxybenzoic acids lack existing exact descriptor identities.'},{'doi':'10.1371/journal.pone.0299037','title':'Modern and traditional cooking methods affect the antioxidant activity and phenolic compounds content of Trachystemon Orientalis','year':2024,'admitted_rows':15,'status':'VERIFIED_PARTIAL','basis':'mg/100 g dry weight','reason':'Table 2 direct raw/cooked caffeic-acid values. Other compounds have raw non-detect and cannot form a concentration ratio.'}]).to_csv(R/'literature_candidate_registry.csv',index=False)
pd.DataFrame([{'category':'EXCLUDED_TABLE_VALUES','doi':'10.3136/fstr.23.193','reason':'Vanillic and p-hydroxybenzoic acid lack an exact established descriptor identity.'},{'category':'EXCLUDED_TABLE_VALUES','doi':'10.1371/journal.pone.0299037','reason':'Protocatechuic and p-coumaric acid are non-detect in raw material; ratios cannot be calculated and are not imputed.'}]).to_csv(R/'excluded_candidates.csv',index=False)
prior=pd.read_csv(R.parent/'batch_006'/'source_verification_ledger.csv');extra=pd.DataFrame([{'doi':'10.3136/fstr.23.193','paper_title':'Combined Effect of Microwave and Steam Cooking on Phytochemical Compounds and Antioxidant Activity of Purple Sweet Potatoes','source_url':'https://www.jstage.jst.go.jp/article/fstr/23/2/23_193/_html/-char/en','locator':'Table 4; Methods cooking techniques and phenolic-acids analysis','rows_admitted':12,'compound':'Chlorogenic acid; caffeic acid; trans-p-coumaric acid','basis':'mg/100 g dry weight','analytical_method':'Individual HPLC UV','admission_status':'VERIFIED_PARTIAL','rationale':'Direct table values and explicitly stated DW basis; cooking procedures triplicated.'},{'doi':'10.1371/journal.pone.0299037','paper_title':'Modern and traditional cooking methods affect the antioxidant activity and phenolic compounds content of Trachystemon Orientalis','source_url':'https://pmc.ncbi.nlm.nih.gov/articles/PMC10890727/','locator':'Table 2; Cooking methods and HPLC methods','rows_admitted':15,'compound':'Caffeic acid','basis':'mg/100 g dry weight','analytical_method':'Individual HPLC-UV','admission_status':'VERIFIED_PARTIAL','rationale':'Direct mean ± SD raw/cooked Table-2 values across five methods and three durations; raw-nondetect compounds excluded.'}]);pd.concat([prior,extra],ignore_index=True,sort=False).to_csv(R/'source_verification_ledger.csv',index=False)
master.groupby('doi').agg(observations=('observation_id','size'),compounds=('compound','nunique'),foods=('food_matrix','nunique'),methods=('cooking_method_normalized','nunique'),bases=('measurement_basis',lambda x:'; '.join(sorted(x.dropna().unique())))).reset_index().to_csv(R/'source_coverage_analysis.csv',index=False)
write('dataset_expansion_report.md',f'''# Scientific dataset expansion — controlled batch 007

The master becomes **{len(master)} verified observations from {master.doi.nunique()} DOI families**. Batch 007 adds 27 direct individual-analyte raw/cooked pairs and preserves 573 parent records.

Chen et al. (2017), DOI `10.3136/fstr.23.193`, Table 4, contributes 12 HPLC dry-weight pairs for chlorogenic, caffeic and trans-p-coumaric acid in purple sweet potato across four fully described steam/microwave protocols. Demirel Ozbek et al. (2024), DOI `10.1371/journal.pone.0299037`, Table 2, contributes 15 dry-weight HPLC-UV caffeic-acid pairs in a consumed Trachystemon leaf-and-stem matrix across five methods and three durations.

No raw-nondetect value is turned into a ratio; all such prospective rows are excluded. No model is retrained; Stage C remains fail-closed. The 1,000 target remains 400 observations away.
''')
write('reproduction_instructions.md','''# Reproduction
Run `python build_batch_007.py`, then `python validate_batch_007.py`. The build reads only Batch 006 and writes only this package; it changes no historical package, Git state, or Stage B/C/D file.
''')
manifest={'package':'StageA_DatasetExpansion1000_Batch007_2026-11-10','parent_rows':573,'parent_sha256':sha(PARENT),'new_rows':27,'total_rows':len(master),'new_doi_families':2,'strict_cross_source_replications_created':0,'target_1000_reached':False,'stage_c_integration_authorized':False};(R/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8');(R/'SHA256SUMS.txt').write_text('\n'.join(f'{sha(p)}  {p.name}' for p in sorted(R.iterdir()) if p.is_file() and p.name!='SHA256SUMS.txt')+'\n',encoding='utf-8');print(json.dumps(manifest,indent=2))
